insert into public.platform_courses(id,document,price) values('course_sec3_full','{"id":"course_sec3_full","title":"المعسكر الذهبي في الأحياء - الصف الثالث الثانوي","subtitle":"شرح تفصيلي شامل لكل أبواب المنهج مع بنك الأسئلة والمراجعات الدورية","grade":"sec3","gradeTitle":"الصف الثالث الثانوي","description":"يغطي منهج الأحياء للثانوية العامة كاملاً (الدعامة والحركة، التنسيق الهرموني، التكاثر، المناعة، والبيولوجيا الجزيئية DNA & RNA) بأحدث النظم التفاعلية والمجسمات ثلاثية الأبعاد.","thumbnail":"/src/assets/images/biology_course_dna_1792884189910.jpg","totalLectures":6,"totalHours":72,"price":450,"isFree":false,"units":[{"id":"u1","unitNumber":1,"title":"الباب الأول: التركيب والوظيفة (الدعامة والحركة)","lecturesCount":10},{"id":"u2","unitNumber":2,"title":"الباب الثاني: التنسيق الهرموني في الكائنات الحية","lecturesCount":8},{"id":"u3","unitNumber":3,"title":"الباب الثالث: التكاثر في الكائنات الحية","lecturesCount":12},{"id":"u4","unitNumber":4,"title":"الباب الرابع: المناعة في الكائنات الحية","lecturesCount":8},{"id":"u5","unitNumber":5,"title":"الباب الخامس: البيولوجيا الجزيئية (DNA & RNA)","lecturesCount":10}]}'::jsonb,450) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_1','course_sec3_full','{"id":"lec_1","playbackProvider":"vdocipher","courseId":"course_sec3_full","unitId":"u1","grade":"sec3","unitTitle":"الباب الأول: الدعامة والحركة","title":"المحاضرة 1: الدعامة الفسيولوجية والدعامة التركيبية في النبات بالتفصيل","description":"شرح الفروق الجوهرية بين الدعامة الفسيولوجية المؤقتة والخاصية الأسموزية، والدعامة التركيبية الدائمة وترسيبات السليلوز واللجنين والكيوتين والسييوبرين مع تجارب معملية وتطبيقات عملية.","videoDuration":"48:20","videoDurationMinutes":48,"videoUrl":"","thumbnail":"/src/assets/images/biology_course_anatomy_1792884201475.jpg","isFreePreview":false,"pdfAttachment":{"title":"ملزمة المحاضرة الأولى - الدعامة في النبات (PDF).pdf","size":"4.8 MB","url":"#"},"associatedQuizId":"quiz_lec_1","order":1,"chapters":[{"time":"00:00","title":"مقدمة الباب الأول والدعامة"},{"time":"08:15","title":"آلية عمل الفجوة العصارية والخاصية الأسموزية"},{"time":"21:30","title":"الدعامة التركيبية والمواد المترسبة"},{"time":"36:45","title":"مقارنات وأفكار امتحانات الثانوية العامة"}]}'::jsonb) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_2','course_sec3_full','{"id":"lec_2","courseId":"course_sec3_full","unitId":"u1","grade":"sec3","unitTitle":"الباب الأول: الدعامة والحركة","title":"المحاضرة 2: الهيكل المحوري في الإنسان (الجمجمة، العمود الفقري، والقفص الصدري)","description":"دراسة تشريحية تفصيلية لفقرات العمود الفقري الـ 33، وأنواع المفاصل، وعدد العظام وطريقة حساب أرقام الفقرات المتصلة بالضلوع بدقة متناهية.","videoDuration":"55:10","videoDurationMinutes":55,"videoUrl":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4","thumbnail":"/src/assets/images/biology_course_anatomy_1792884201475.jpg","isFreePreview":true,"pdfAttachment":{"title":"مخطط تشريح الهيكل العظمي المحوري والطرفي.pdf","size":"6.2 MB","url":"#"},"associatedQuizId":"quiz_lec_2","order":2,"chapters":[{"time":"00:00","title":"تقسيم الهيكل العظمي في الإنسان"},{"time":"12:00","title":"أنواع فقرات العمود الفقري"},{"time":"30:20","title":"الجمجمة والقفص الصدري وعظمة القص"},{"time":"44:00","title":"حل التريكات الرياضية لعدد العظام"}]}'::jsonb) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_3','course_sec3_full','{"id":"lec_3","courseId":"course_sec3_full","unitId":"u1","grade":"sec3","unitTitle":"الباب الأول: الدعامة والحركة","title":"المحاضرة 3: فسيولوجيا الانقباض العضلي ونظرية الخيوط المنزلقة (هكسلي)","description":"شرح كيميائي وكهربائي لنقل السيال العصبي عبر التشابك العصبي العضلي، ودور أيونات الكالسيوم وATP والروابط المستعرضة في انقباض وانبساط اللييفة العضلية.","videoDuration":"52:40","videoDurationMinutes":52,"videoUrl":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4","thumbnail":"/src/assets/images/biology_course_anatomy_1792884201475.jpg","isFreePreview":false,"pdfAttachment":{"title":"ملزمة ميكانيكا الانقباض العضلي وإجهاد العضلة.pdf","size":"5.1 MB","url":"#"},"associatedQuizId":"quiz_lec_3","order":3,"chapters":[{"time":"00:00","title":"تركيب العضلة الهيكلية والقطع العضلية"},{"time":"15:10","title":"الوصلة العصبية العضلية والأسيتيل كولين"},{"time":"32:00","title":"دور الكالسيوم وATP ونظرية هكسلي"},{"time":"45:30","title":"الشد العضلي والإجهاد وحمض اللاكتيك"}]}'::jsonb) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_4','course_sec3_full','{"id":"lec_4","courseId":"course_sec3_full","unitId":"u2","grade":"sec3","unitTitle":"الباب الثاني: التنسيق الهرموني","title":"المحاضرة 4: سيدة الغدد الصماء (الغدة النخامية وهرمونات النمو والتحكم)","description":"دراسة هرمونات الفص الأمامي والخلفي، التغذية الراجعة السلبية والإيجابية، وعلاقة تحت المهاد (الهيبوثالامس) بإفراز هرمون ADH والأوكسيتوسين.","videoDuration":"46:15","videoDurationMinutes":46,"videoUrl":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4","thumbnail":"/src/assets/images/biology_course_dna_1792884189910.jpg","isFreePreview":false,"pdfAttachment":{"title":"خريطة ذهنية لهرمونات الغدة النخامية والغدد المستهدفة.pdf","size":"3.9 MB","url":"#"},"associatedQuizId":"quiz_lec_4","order":4}'::jsonb) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_5','course_sec3_full','{"id":"lec_5","courseId":"course_sec3_full","unitId":"u5","grade":"sec3","unitTitle":"الباب الخامس: البيولوجيا الجزيئية","title":"المحاضرة 5: اكتشاف المادة الوراثية وتركيب لولب الـ DNA المزدوج ثلاثي الأبعاد","description":"تجارب جريفث وإيفري وهيرشي وتشيس، تحليل فرانكلين بالأشعة السينية، وبناء نموذج واطسون وكريك للـ DNA مع القواعد النيتروجينية والروابط الهيدروجينية.","videoDuration":"58:30","videoDurationMinutes":58,"videoUrl":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4","thumbnail":"/src/assets/images/biology_course_dna_1792884189910.jpg","isFreePreview":true,"pdfAttachment":{"title":"ملزمة البيولوجيا الجزيئية وحسابات القواعد النيتروجينية.pdf","size":"7.4 MB","url":"#"},"associatedQuizId":"quiz_lec_5","order":5}'::jsonb) on conflict(id) do nothing;
insert into public.platform_lectures(id,course_id,document) values('lec_6','course_sec3_full','{"id":"lec_6","courseId":"course_sec3_full","unitId":"u5","grade":"sec3","unitTitle":"الباب الخامس: البيولوجيا الجزيئية","title":"المحاضرة 6: تضاعف الـ DNA، إنزيمات البلمرة والربط واللولب وإصلاح عيوب النواة","description":"كيف يتضاعف شريط DNA بدقة فائقة؟ دور إنزيم اللولب (Helicase)، وإنزيم بلمرة DNA في الشريطين المتصل والمتقطع (قطع أوكازاكي)، ودور إنزيمات الربط في الإصلاح والتنوع الوراثي.","videoDuration":"62:00","videoDurationMinutes":62,"videoUrl":"https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyBlazes.mp4","thumbnail":"/src/assets/images/biology_course_dna_1792884189910.jpg","isFreePreview":false,"pdfAttachment":{"title":"مسائل قوانين الـ DNA وحساب النسب المئوية.pdf","size":"4.2 MB","url":"#"},"associatedQuizId":"quiz_lec_6","order":6}'::jsonb) on conflict(id) do nothing;
